/// Returns the median of `values`, or `None` when the input is empty.
///
/// The values are copied into a sorted slice. For an odd number of elements the
/// middle element is returned; for an even number the mean of the two middle
/// elements is returned. Sums are accumulated with `i128` so that the
/// `i64::MAX` + `i64::MAX` case cannot overflow.
pub fn median(values: &[i64]) -> Option<f64> {
    let mut sorted = values.to_vec();
    sorted.sort();

    let len = sorted.len();
    let middle = len.checked_div(2)?;

    if len % 2 == 0 {
        let lower = sorted[middle - 1];
        let upper = sorted[middle];
        Some(((lower as i128 + upper as i128) / 2) as f64)
    } else {
        Some(sorted[middle] as f64)
    }
}

#[cfg(test)]
mod tests {
    use super::median;

    #[test]
    fn empty_input_is_none() {
        assert_eq!(median(&[]), None);
    }

    #[test]
    fn odd_length() {
        assert_eq!(median(&[3, 1, 2]), Some(2.0));
        assert_eq!(median(&[1, 2, 3, 4, 5]), Some(3.0));
    }

    #[test]
    fn even_length() {
        assert_eq!(median(&[1, 3]), Some(2.0));
        assert_eq!(median(&[3, 1, 2, 4]), Some(2.5));
    }

    #[test]
    fn already_sorted() {
        assert_eq!(median(&[1, 2, 3]), Some(2.0));
        assert_eq!(median(&[1, 2, 3, 4]), Some(2.5));
    }

    #[test]
    fn no_overflow_with_i64_max() {
        let max = i64::MAX;
        assert_eq!(median(&[max, max]), Some(max as f64));
        assert_eq!(
            median(&[i64::MIN, i64::MAX]),
            Some((i64::MIN as i128 + i64::MAX as i128) / 2 as f64)
        );
    }
}

